#!/bin/bashset -e# 在 docker 初始化脚本中，如果提供了导出的 SQL，可以在这里执行# 目前系统在后端应用启动时，如果表不存在，SQLAlchemy 的 create_all 会自动建表。# 这里只负责创建数据库和用户psql -v ON_ERROR_STOP=1 --username "$POSTGRES_USER" --dbname "$POSTGRES_DB" <<-EOSQL    CREATE USER ctms_user WITH PASSWORD 'ctms2026';    CREATE DATABASE ctms_pro;    GRANT ALL PRIVILEGES ON DATABASE ctms_pro TO ctms_user;    \c ctms_pro    GRANT ALL ON SCHEMA public TO ctms_user;EOSQL